function(params) {
  if (api.getState && api.getState() !== 'play') return { error: true, message: '⚠️ 请先按 Enter 开始游戏再使用道具' };
  var secs = (params && params.seconds) ? params.seconds : 5;
  if (secs > 10) secs = 10;
  var frames = Math.round(secs * 60);
  if (api.startFly) api.startFly(frames);
  else if (game) game.flyTimer = frames;
  return { message: '🪽 羽翼展开！飞行 ' + secs + ' 秒，按住跳跃键上升' };
}
